import {BARON_FONT} from "../../constant/assets.js";

var BTN_CLT_OR = "data:image/png;base64,";
var BTN_CLT_WARRIOR = "data:image/png;base64,";

const WARRIOR_IMGS = [
  "data:image/webp;base64,",
  "data:image/webp;base64,",
  "data:image/webp;base64,",
  "data:image/webp;base64,",
  "data:image/webp;base64,",
];

const COLORS = [
  { h: "#3B82F6" }, { h: "#EAB308" }, { h: "#EF4444" }, { h: "#22C55E" }
];

export default function CollectPopup({ collectChoice, pl, onArmy, onTax }) {
  if (!collectChoice) return null;

  var color    = pl ? pl.color : "#FCD34D";
  var clanIdx  = Math.max(0, COLORS.findIndex(function(c) { return c.h === color; })) + 1;
  var wBtn     = WARRIOR_IMGS[clanIdx] || WARRIOR_IMGS[0];

  return (
    <div className="anim-fade" style={{ position: "fixed", top: 0, left: 0, right: 0, bottom: 0, background: "rgba(0,0,0,0.82)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 1000 }}>
      <style>{`@font-face { font-family: 'BaronNeue'; src: url('${BARON_FONT}') format('opentype'); }`}</style>
      <div style={{ position: "relative", maxWidth: 320, width: "90%", background: "#000", borderRadius: 12, padding: "24px 16px 20px 16px" }}>

        <div style={{ textAlign: "center", marginBottom: 24 }}>
          <span style={{ fontFamily: "'BaronNeue','Black Ops One',serif", fontWeight: 700, fontSize: 12, color: "#fff", letterSpacing: "0.08em" }}>
            Choix de collecte
          </span>
        </div>

        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-around", gap: 8 }}>

          {/* Bouton warrior */}
          <div onClick={onArmy} style={{ cursor: "pointer", width: "60%", position: "relative", overflow: "hidden" }}>
            <img src={BTN_CLT_WARRIOR} style={{ width: "80%", display: "block" }} alt="Soldats" />
            <img src={wBtn} style={{ position: "absolute", top: "50%", left: "55%", transform: "translate(-50%,-50%)", width: "35%", objectFit: "contain" }} alt="" />
          </div>

          {/* Bouton or */}
          <div onClick={onTax} style={{ cursor: "pointer", width: "60%" }}>
            <img src={BTN_CLT_OR} style={{ width: "80%", display: "block" }} alt="Or" />
          </div>

        </div>
      </div>
    </div>
  );
}
